command:
set -eu
printf 'final_source_home_tree_metadata\n'
for u in mira niko sana; do sudo find "/home/$u" -xdev -printf '%p|type=%y|mode=%m|uid=%U|gid=%G|size=%s|mtime=%T@|links=%n|target=%l\n' | LC_ALL=C sort; done
printf 'final_source_regular_file_sha256\n'
for u in mira niko sana; do sudo find "/home/$u" -xdev -type f -exec sha256sum {} + | LC_ALL=C sort; done
printf 'final_source_xattr_inventory\n'
sudo python3 - <<'PY'
from __future__ import print_function
import os, hashlib
for top in ('/home/mira','/home/niko','/home/sana'):
    for root, dirs, files in os.walk(top):
        for p in sorted([root]+[os.path.join(root,n) for n in files]):
            try:
                names=sorted(os.listxattr(p, follow_symlinks=False))
            except (OSError, TypeError):
                names=[]
            for name in names:
                try:
                    val=os.getxattr(p,name,follow_symlinks=False)
                    digest=hashlib.sha256(val).hexdigest()
                except OSError:
                    digest='unreadable'
                print('%s|%s|%s' % (p,name,digest))
PY

